use rusqlite::{params, Connection}; use serde::{Deserialize, Serialize}; use std::path::PathBuf; use std::sync::Mutex; pub struct DbState { pub conn: Mutex<Connection>, } #[derive(Debug, Clone, Serialize, Deserialize)] pub struct WorkspaceData { pub name: String, pub nodes_json: String, pub edges_json: String, pub dialect: String, pub plan: String, } fn db_path() -> PathBuf { let base = dirs::data_dir().unwrap_or_else(|| PathBuf::from(".")); base.join("novadb").join("novadb.sqlite") } pub fn init_db() -> Result<Connection, String> { let path = db_path(); if let Some(parent) = path.parent() { std::fs::create_dir_all(parent).map_err(|e| e.to_string())?; } let conn = Connection::open(&path).map_err(|e| e.to_string())?; conn.execute_batch( "CREATE TABLE IF NOT EXISTS workspaces ( name TEXT PRIMARY KEY, nodes_json TEXT NOT NULL DEFAULT '[]', edges_json TEXT NOT NULL DEFAULT '[]', dialect TEXT NOT NULL DEFAULT 'Postgres', plan TEXT NOT NULL DEFAULT 'goliaf', updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')) ); CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );", ) .map_err(|e| e.to_string())?; Ok(conn) } pub fn save_workspace(conn: &Connection, data: &WorkspaceData) -> Result<(), String> { conn.execute( "INSERT INTO workspaces (name, nodes_json, edges_json, dialect, plan, updated_at) VALUES (?1, ?2, ?3, ?4, ?5, strftime('%s','now')) ON CONFLICT(name) DO UPDATE SET nodes_json = excluded.nodes_json, edges_json = excluded.edges_json, dialect = excluded.dialect, plan = excluded.plan, updated_at = excluded.updated_at", params![ data.name, data.nodes_json, data.edges_json, data.dialect, data.plan ], ) .map_err(|e| e.to_string())?; Ok(()) } pub fn load_workspace(conn: &Connection, name: &str) -> Result<Option<WorkspaceData>, String> { let mut stmt = conn .prepare("SELECT name, nodes_json, edges_json, dialect, plan FROM workspaces WHERE name = ?1") .map_err(|e| e.to_string())?; let mut rows = stmt.query(params![name]).map_err(|e| e.to_string())?; if let Some(row) = rows.next().map_err(|e| e.to_string())? { return Ok(Some(WorkspaceData { name: row.get(0).map_err(|e| e.to_string())?, nodes_json: row.get(1).map_err(|e| e.to_string())?, edges_json: row.get(2).map_err(|e| e.to_string())?, dialect: row.get(3).map_err(|e| e.to_string())?, plan: row.get(4).map_err(|e| e.to_string())?, })); } Ok(None) } pub fn list_workspaces(conn: &Connection) -> Result<Vec<String>, String> { let mut stmt = conn .prepare("SELECT name FROM workspaces ORDER BY updated_at DESC") .map_err(|e| e.to_string())?; let names = stmt .query_map([], |row| row.get(0)) .map_err(|e| e.to_string())? .filter_map(|r| r.ok()) .collect(); Ok(names) } pub fn delete_workspace(conn: &Connection, name: &str) -> Result<(), String> { conn.execute("DELETE FROM workspaces WHERE name = ?1", params![name]) .map_err(|e| e.to_string())?; Ok(()) } pub fn get_setting(conn: &Connection, key: &str) -> Result<Option<String>, String> { let mut stmt = conn .prepare("SELECT value FROM settings WHERE key = ?1") .map_err(|e| e.to_string())?; let mut rows = stmt.query(params![key]).map_err(|e| e.to_string())?; if let Some(row) = rows.next().map_err(|e| e.to_string())? { return Ok(Some(row.get(0).map_err(|e| e.to_string())?)); } Ok(None) } pub fn set_setting(conn: &Connection, key: &str, value: &str) -> Result<(), String> { conn.execute( "INSERT INTO settings (key, value) VALUES (?1, ?2) ON CONFLICT(key) DO UPDATE SET value = excluded.value", params![key, value], ) .map_err(|e| e.to_string())?; Ok(()) }